Rules.InvariantScript:
App.Height
// THE COMPONENT COVERS THE APP, and the instance can still override it.
// App.Height is the one height in this file that is not derived from
// anything inside the dialog, which is what makes it safe to cap
// against.

Set(_cmpRerouteMode, "temporary");
Set(_cmpRerouteAssignee, "");
Set(_cmpRerouteAssigneeEmail, "");
Set(_cmpRerouteReason, "");
Reset(cmbRerPerson_1)
// RESET ON CLOSE, NOT ON OPEN. A canvas component has no lifecycle
// events at all: no OnVisible, no OnHidden, no OnStart. Reset() is the
// only hook and something outside has to call it. The screen calls it
// on both close paths, which it is already writing.
//
// Mode defaults to temporary rather than blank, so one of the two
// buttons is always lit and the help text underneath always says
// something true. A blank mode with both buttons grey reads as broken.
//
// Reset on the combo box clears BOTH its typed text and its selection.
// The modern control does not reliably fire OnChange on Reset, so the
// globals above are cleared here as well; clearing one without the
// other leaves the dialog claiming a person it will not actually send.

Max(nfSpace.Xl, (Parent.Height - Self.Height) / 2)
// Max, SO CENTRING CANNOT GO NEGATIVE. Once the panel is taller
// than the space it has, it pins to the top with a margin
// instead of hanging off it. Unbounded centring is what put the
// footer buttons below the bottom edge.

conRerHeader_1.Height
+ conRerBody_1.Height
+ conRerFooter_1.Height
// A PLAIN SUM OF THE THREE BANDS, and not one of them reads back
// up to this control. An earlier version capped this with
// Min(sum, Parent.Height - ...) while the body capped itself
// against this panel, which is a straight cycle and Studio
// rejects it: "a property cannot reference itself or other
// properties affected by its value".
//
// The cap belongs on the body, against App.Height, which nothing
// in this dialog can influence.

Min(
    conRerTask_1.Height + conRerType_1.Height + conRerAssign_1.Height + conRerReason_1.Height + 3 * Self.LayoutGap + Self.PaddingTop + Self.PaddingBottom,
    App.Height - conRerHeader_1.Height - conRerFooter_1.Height - 4 * nfSpace.Xl
)
// THE BODY IS THE PART THAT SCROLLS. Header and footer are
// fixed bands, so the confirm button is always reachable no
// matter how tall the content gets or how short the viewport
// is. This is the behaviour every dialog should have had from
// the start; without it a phone user cannot reach Cancel.

With(
    { a: LookUp(colAssignments, AssignmentKey = cmpDetReroute.AssignmentKey) },
    a.AssigneeName
    & "   •   "
    & LookUp(nfDepartments, ConfigKey = a.DepartmentCode).Title
)
// AssignmentKey is qualified with the component name
// because the record scope of LookUp also has a column
// called AssignmentKey. Unqualified, the input property is
// shadowed and the LookUp compares the column to itself,
// matching every row.

Set(_cmpRerouteMode, "temporary")
// Set, NOT UpdateContext. A component has no context
// variables at all, so every loc in the original
// overlay became an underscore prefixed global.
//
// "temporary" is the key the flow reads. The button
// text can be reworded freely; this string cannot.

ThisItem.DisplayName & "   -   " & ThisItem.Mail
// A FORMULA, SO IT SURVIVES A PASTE. The classic picker
// took DisplayFields plus a Layout template that lives
// outside Properties, and always landed on Single.

false
// WRITTEN EXPLICITLY. The modern default is true, and a
// reroute goes to exactly one person.

true
// SearchText UPDATES ON A PAUSE, NOT PER KEYSTROKE. Same
// reason as cmpSendEmail: nfDirectory hits Office365Users,
// which throttles per user per connection, and only the
// last of five keystroke queries was ever wanted.

If(
    !IsBlank(_cmpRerouteAssigneeEmail)
        && _cmpRerouteAssigneeEmail
           = Lower(LookUp(colAssignments, AssignmentKey = cmpDetReroute.AssignmentKey).AssigneeEmail),
    ValidationState.Error,
    ValidationState.None
)
// THE CURRENT OWNER IS AN ERROR ON THE PICKER, not just a
// silently disabled Reroute button. Same test as the
// third guard on btnRerSubmit, so the two cannot disagree.

With(
    { p: First(Self.SelectedItems) },
    If(
        IsBlank(p.Mail),
        Set(_cmpRerouteAssignee, "");
        Set(_cmpRerouteAssigneeEmail, ""),
        Set(_cmpRerouteAssignee, p.DisplayName);
        Set(_cmpRerouteAssigneeEmail, Lower(Trim(p.Mail)))
    )
)
// DESELECTING CLEARS THE PERSON. The modern control fires
// OnChange on deselection too, so the globals now follow
// the picker both ways. The classic version only ever
// set them, so clearing the box left the old person
// queued to be sent.
//
// A picked row with no Mail also clears, because the flow
// acts on the email and a name alone is not an identity.

If(
    IsBlank(_cmpRerouteAssigneeEmail),
    "No one chosen yet.",
    _cmpRerouteAssigneeEmail
        = Lower(LookUp(colAssignments, AssignmentKey = cmpDetReroute.AssignmentKey).AssigneeEmail),
    _cmpRerouteAssignee & " already has this task. Pick someone else.",
    "Reassigning to " & _cmpRerouteAssignee
    & "   •   " & _cmpRerouteAssigneeEmail
)
// THE CHOICE STATED IN WORDS, and the reason the picker is
// red when it is. Error state is never carried by colour
// alone.

If(
    !nfIsFullVersion
        || IsBlank(_cmpRerouteAssigneeEmail)
        || IsBlank(Trim(_cmpRerouteReason))
        || Lower(_cmpRerouteAssigneeEmail)
           = Lower(LookUp(colAssignments, AssignmentKey = cmpDetReroute.AssignmentKey).AssigneeEmail),
    DisplayMode.Disabled,
    DisplayMode.Edit
)
// THREE GUARDS. A person, a reason, and not the person who
// already has it. Rerouting a task to its current owner is a
// no-op that still writes an audit row and still sends a
// notification, which is worse than doing nothing.
//
// A reason is required here where it is optional on an
// approval, because a reroute is something that happened to
// someone else's work and this is the only place it is
// explained. The flow validates all three again: a disabled
// button is a courtesy, not a control.

cmpDetReroute.OnSubmit()
// RAISES THE EVENT AND NOTHING ELSE. No Patch, no flow call, no
// Navigate. The screen reads Mode, AssigneeEmail, AssigneeName
// and Reason off the instance and calls RerouteAssignment.
